import { Component, OnInit } from "@angular/core";
import { Router } from "@angular/router";
import { HttpErrorResponse } from "@angular/common/http";
import { AuthService } from "../../auth/auth.service";

type AuthMode = "login" | "signup";

@Component({
  selector: "app-login",
  templateUrl: "./login.component.html",
  styleUrls: ["./login.component.scss"],
  host: {
    class: "fill-screen",
    dir: "ltr",
    lang: "en",
  },
})
export class LoginComponent implements OnInit {
  mode: AuthMode = "login";

  username = "";
  password = "";

  signupEmail = "";
  signupPassword = "";
  signupPasswordConfirm = "";

  errorMessage = "";
  isSubmitting = false;

  constructor(
    private authService: AuthService,
    private router: Router,
  ) {}

  ngOnInit(): void {
    if (this.authService.isAuthenticated()) {
      void this.router.navigate(["/config"]);
    }
  }

  showLogin(): void {
    this.mode = "login";
    this.errorMessage = "";
  }

  showSignup(): void {
    this.mode = "signup";
    this.errorMessage = "";
  }

  onLoginSubmit(): void {
    this.errorMessage = "";
    this.isSubmitting = true;

    this.authService.login(this.username.trim(), this.password).subscribe({
      next: () => {
        this.isSubmitting = false;
        void this.router.navigate(["/config"]);
      },
      error: (err: HttpErrorResponse) => {
        this.isSubmitting = false;
        this.errorMessage = this.httpErrorMessage(err, "Login failed");
      },
    });
  }

  onSignupSubmit(): void {
    this.errorMessage = "";

    if (this.signupPassword !== this.signupPasswordConfirm) {
      this.errorMessage = "Passwords do not match";
      return;
    }

    this.isSubmitting = true;

    this.authService
      .signup(
        this.signupEmail.trim(),
        this.signupPassword,
        this.signupPasswordConfirm,
      )
      .subscribe({
        next: () => {
          this.isSubmitting = false;
          void this.router.navigate(["/config"]);
        },
        error: (err: HttpErrorResponse) => {
          this.isSubmitting = false;
          this.errorMessage = this.httpErrorMessage(err, "Sign up failed");
        },
      });
  }

  private httpErrorMessage(err: HttpErrorResponse, fallback: string): string {
    const body = err.error as { message?: string } | undefined;
    return body?.message ?? err.message ?? fallback;
  }
}
<div class="card">
  <h1>{{ mode === "login" ? "Sign in" : "Sign up" }}</h1>
  <p class="subtitle">Manychat Translator</p>
  <p class="error" *ngIf="errorMessage">{{ errorMessage }}</p>

  <form *ngIf="mode === 'login'" (ngSubmit)="onLoginSubmit()">
    <div class="field">
      <label for="username">Username or email</label>
      <input
        id="username"
        name="username"
        type="text"
        autocomplete="username"
        required
        [(ngModel)]="username"
      />
    </div>
    <div class="field">
      <label for="password">Password</label>
      <input
        id="password"
        name="password"
        type="password"
        autocomplete="current-password"
        required
        [(ngModel)]="password"
      />
    </div>
    <button type="submit" [disabled]="isSubmitting">Log in</button>
    <button
      type="button"
      class="btn-link"
      [disabled]="isSubmitting"
      (click)="showSignup()"
    >
      Sign up
    </button>
  </form>

  <form *ngIf="mode === 'signup'" (ngSubmit)="onSignupSubmit()">
    <div class="field">
      <label for="signup-email">Email</label>
      <input
        id="signup-email"
        name="email"
        type="email"
        autocomplete="email"
        required
        [(ngModel)]="signupEmail"
      />
    </div>
    <div class="field">
      <label for="signup-password">Password</label>
      <input
        id="signup-password"
        name="password"
        type="password"
        autocomplete="new-password"
        required
        [(ngModel)]="signupPassword"
      />
    </div>
    <div class="field">
      <label for="signup-password-confirm">Confirm password</label>
      <input
        id="signup-password-confirm"
        name="passwordConfirm"
        type="password"
        autocomplete="new-password"
        required
        [(ngModel)]="signupPasswordConfirm"
      />
    </div>
    <button type="submit" [disabled]="isSubmitting">Create account</button>
    <button
      type="button"
      class="btn-link"
      [disabled]="isSubmitting"
      (click)="showLogin()"
    >
      Already have an account? Sign in
    </button>
  </form>
</div>
